package mz.co.aprendaacodar.question.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.QuestionStatus;import mz.co.aprendaacodar.course.entity.Lesson;import mz.co.aprendaacodar.user.entity.User;
@Entity @Table(name="lesson_questions") public class LessonQuestion extends BaseEntity {@ManyToOne(optional=false,fetch=FetchType.LAZY) private Lesson lesson;@ManyToOne(optional=false,fetch=FetchType.LAZY) private User student;@Column(nullable=false,columnDefinition="TEXT") private String content;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private QuestionStatus status=QuestionStatus.OPEN;protected LessonQuestion(){}public LessonQuestion(Lesson l,User s,String c){lesson=l;student=s;content=c;}public Lesson getLesson(){return lesson;}public User getStudent(){return student;}public String getContent(){return content;}public QuestionStatus getStatus(){return status;}public void answered(){if(status==QuestionStatus.OPEN)status=QuestionStatus.ANSWERED;}public void close(){status=QuestionStatus.CLOSED;}}
